CREATE TABLE FastConsig.dbo.Bancos (
  Id int IDENTITY,
  Banco varchar(3) NOT NULL,
  Digito varchar(1) NULL,
  Nome varchar(150) NOT NULL,
  Cnpj varchar(14) NOT NULL,
  Ativo bit NOT NULL,
  ISPB varchar(8) NULL,
  CBCDataPrev varchar(3) NULL,
  CONSTRAINT PK_Bancos_Banco PRIMARY KEY CLUSTERED (Banco)
)
ON [PRIMARY]
GO

